// CSD_RATIONALE_BEGIN
// ROOT CAUSE ANALYSIS:
// Best attempt (40.8%) uses `next == "<<"` which rarely fires due to tokenizer
// space-prefixing. So organic `<<expr>>` spans run as FREE TEXT. This works for
// ~40% of examples where the model naturally writes the correct final answer in
// its last organic span. It fails when:
//   (a) The last organic span is an intermediate expression, not the final answer.
//   (b) The model writes `{n1}*{mult}` with curly braces in free text, which
//       fails the evaluator's syntax check.
//   (c) The model enters a repetition loop (`* k_2 / k_2 * k_2 / k_2...`) in
//       free text, filling the budget before reaching the final answer.
//
// KEY FIXES over best attempt:
// 1. Use `RenderedEndsWith(generated, "<<")` instead of `next == "<<"`.
//    This catches organic `<<` even when the tokenizer prepends a space.
//    Now ALL `<<expr>>` spans are under parser control. The hard mask FORCES the
//    model to write identifiers WITHOUT curly braces (parser rejects `{`),
//    turning `{n1}*{mult}` into `n1*mult` automatically.
// 2. Inside constrained spans: use `RepetitionPenaltyStep` with penalty on
//    `generated` to break `* k_2 / k_2` repetition loops. The model stays on
//    topic and generates the full correct expression.
// 3. Do NOT close eagerly on `IsCompletePrefix`; only close when the LM signals
//    EOS (model is naturally done) or budget pressure forces close via
//    `CloseSpanWithinBudget`. This allows multi-term expressions like
//    `n + k_2*n + k_3*n + k_3*n//2 + k_3*n//8` to be written fully.
// 4. On EOS inside the span: if complete, close; else force-close with budget.
// 5. Brief, non-curly-brace guidance reinforces the grammar.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//
//   Outside-span branch (!insideConstrainedOut):
//     The implication is vacuously true. When `RenderedEndsWith(generated,"<<")`,
//     `EnterObservedConstrainedSpan` sets currentConstrainedOut := [], and
//     parser.IsValidPrefix([]) holds by method precondition.
//
//   Budget-pressure branch (CloseSpanWithinBudget):
//     The helper's postcondition guarantees
//     `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`.
//     We then set steps := maxSteps and break, exiting with the invariant intact.
//
//   Normal inside-span branch (RepetitionPenaltyStep → AppendConstrainedToken):
//     RepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS; a non-EOS
//     result `next` satisfies `IsTokenValidNext(parser, currentConstrainedOut, next)`.
//     AppendConstrainedToken extends currentConstrainedOut by that token, so
//     parser.IsValidPrefix(currentConstrainedOut + [next]) holds.
//
//   EOS sub-branch (complete): CloseConstrainedSpan sets insideConstrainedOut :=
//     false, making the implication vacuously true, and currentConstrainedOut := [].
//   EOS sub-branch (not complete): CloseSpanWithinBudget postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2: progress
//   `|generated| <= |generatedPrefix| + steps`
//
//   Outside-span branch: UnconstrainedStep costs one step (steps += 1).
//     EOS breaks without appending; otherwise generated grows by exactly 1.
//     EnterObservedConstrainedSpan leaves |generated| unchanged. Preserved.
//
//   Budget-pressure (CloseSpanWithinBudget): closeBudget = maxSteps - steps.
//     Postcondition: |generatedOut| <= |generated_before| + closeBudget.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps. Preserved.
//
//   Normal inside-span: RepetitionPenaltyStep costs +1 step (steps += 1),
//     AppendConstrainedToken appends exactly 1 token. Preserved.
//
//   EOS + CloseConstrainedSpan: CloseConstrainedSpan costs +1 step (steps += 1),
//     appends at most 1 token (">>"). We checked maxSteps - steps >= 1 before
//     calling it, so steps stays <= maxSteps. Preserved.
//
//   EOS + CloseSpanWithinBudget: same argument as budget-pressure branch. Preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Solve step by step. For each arithmetic sub-expression and the final answer, emit << expression >> using only identifiers (letters, digits, underscores), numbers, and operators +,-,*,/,//,%,** and parentheses. No curly braces inside << >>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      generated, insideConstrainedOut, currentConstrainedOut :=
        helpers.EnterObservedConstrainedSpan(lm, generated);
    }
  } else {
    // Inside a constrained span.
    if maxSteps - steps <= 3 {
      // Budget pressure: close whatever we have via CloseSpanWithinBudget.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Generate next constrained token with repetition penalty to break loops.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.RepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 1.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // Model signals it is done with the expression.
        if parser.IsCompletePrefix(currentConstrainedOut) {
          if maxSteps - steps >= 1 {
            var cg, ci, cc := helpers.CloseConstrainedSpan(
              lm, parser, generated, currentConstrainedOut
            );
            generated := cg;
            insideConstrainedOut := ci;
            currentConstrainedOut := cc;
            steps := steps + 1;
          }
        } else if maxSteps - steps >= 1 {
          var closeBudget := maxSteps - steps;
          var cg, ci, cc := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
          );
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := maxSteps;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

